use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_ascii_letter(c: char) -> bool {
    ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
}

spec fn check_if_last_char_is_a_letter_spec(txt: &str) -> bool {
    &&& txt.len() > 0
    &&& is_ascii_letter(txt@.last_char())
    &&& (txt.len() == 1 || txt@.index(txt.len() - 2) == ' ')
}

fn check_if_last_char_is_a_letter(txt: &str) -> (b: bool)
    ensures
        b == check_if_last_char_is_a_letter_spec(txt),
{
    // First check if the string is non-empty
    if txt.len() == 0 {
        return false;
    }
    
    // Get the last character
    let last_char = txt.chars().last().unwrap();
    
    // Check if it's an ASCII letter
    if !(('a' <= last_char && last_char <= 'z') || ('A' <= last_char && last_char <= 'Z')) {
        return false;
    }
    
    // Check the second condition: either length is 1 or second-to-last char is space
    if txt.len() == 1 {
        return true;
    }
    
    // Get the second-to-last character
    let second_last_char = txt.chars().nth(txt.len() - 2).unwrap();
    
    // Return whether it's a space
    second_last_char == ' '
}

}